    org.jsoup.nodes.Document doc = org.jsoup.Jsoup.parse("<div><p>text</p></div>");
    org.jsoup.nodes.Element div = doc.select("div").first();
    final int[] headCount = {0};
    final int[] tailCount = {0};
    NodeVisitor visitor = new NodeVisitor() {
        public void head(Node node, int depth) { headCount[0]++; }
        public void tail(Node node, int depth) { tailCount[0]++; }
    };
    NodeTraversor traversor = new NodeTraversor(visitor);
    traversor.traverse(div);
    assertTrue(headCount[0] > 0);
    assertEquals(headCount[0], tailCount[0]);
}

@Test
public void testTraverseElements() {
    org.jsoup.nodes.Document doc = org.jsoup.Jsoup.parse("<ul><li>a</li><li>b</li></ul>");
    Elements lis = doc.select("li");
    final int[] count = {0};
    NodeTraversor.traverse(new NodeVisitor() {
        public void head(Node node, int depth) { count[0]++; }
        public void tail(Node node, int depth) {}
    }, lis);
    assertTrue(count[0] >= 2);
}

