@Test
public void testFilterSkipChildren() {
    org.jsoup.nodes.Document doc = org.jsoup.Jsoup.parse("<div><p><span>text</span></p></div>");
    org.jsoup.nodes.Element div = doc.select("div").first();
    final java.util.List<String> heads = new java.util.ArrayList<>();
    FilterResult result = NodeTraversor.filter(new NodeFilter() {
        public FilterResult head(Node node, int depth) {
            heads.add(node.nodeName());
            if ("p".equals(node.nodeName())) return FilterResult.SKIP_CHILDREN;
            return FilterResult.CONTINUE;
        }
        public FilterResult tail(Node node, int depth) { return FilterResult.CONTINUE; }
    }, div);
    assertTrue(heads.contains("div"));
    assertTrue(heads.contains("p"));
    assertFalse(heads.contains("span"));
}

@Test
public void testFilterRemoveNode() {
    org.jsoup.nodes.Document doc = org.jsoup.Jsoup.parse("<div><p id='remove'>to remove</p><p id='keep'>keep</p></div>");
    org.jsoup.nodes.Element div = doc.select("div").first();
    NodeTraversor.filter(new NodeFilter() {
        public FilterResult head(Node node, int depth) {
            if ("p".equals(node.nodeName()) && "remove".equals(node.attr("id"))) {
                return FilterResult.REMOVE;
            }
            return FilterResult.CONTINUE;
        }
        public FilterResult tail(Node node, int depth) { return FilterResult.CONTINUE; }
    }, div);
    assertEquals(0, doc.select("#remove").size());
    assertEquals(1, doc.select("#keep").size());
}

