@Test
public void testFilterElementsStopsOnStop() {
    org.jsoup.nodes.Document doc = org.jsoup.Jsoup.parse("<ul><li id='a'>a</li><li id='b'>b</li><li id='c'>c</li></ul>");
    Elements lis = doc.select("li");
    final java.util.List<String> visited = new java.util.ArrayList<>();
    NodeTraversor.filter(new NodeFilter() {
        public FilterResult head(Node node, int depth) {
            if ("li".equals(node.nodeName())) {
                visited.add(node.attr("id"));
                if ("b".equals(node.attr("id"))) return FilterResult.STOP;
            }
            return FilterResult.CONTINUE;
        }
        public FilterResult tail(Node node, int depth) { return FilterResult.CONTINUE; }
    }, lis);
    assertTrue(visited.contains("a"));
    assertTrue(visited.contains("b"));
    assertFalse(visited.contains("c"));
}

@Test
public void testFilterStopInTail() {
    org.jsoup.nodes.Document doc = org.jsoup.Jsoup.parse("<div><p>text</p></div>");
    org.jsoup.nodes.Element div = doc.select("div").first();
    FilterResult result = NodeTraversor.filter(new NodeFilter() {
        public FilterResult head(Node node, int depth) { return FilterResult.CONTINUE; }
        public FilterResult tail(Node node, int depth) {
            if ("p".equals(node.nodeName())) return FilterResult.STOP;
            return FilterResult.CONTINUE;
        }
    }, div);
    assertEquals(FilterResult.STOP, result);
}

@Test
public void testTraverseDepthTracking() {
    org.jsoup.nodes.Document doc = org.jsoup.Jsoup.parse("<div><p><span>text</span></p></div>");
    org.jsoup.nodes.Element div = doc.select("div").first();
    final java.util.Map<String, Integer> depths = new java.util.HashMap<>();
    NodeTraversor.traverse(new NodeVisitor() {
        public void head(Node node, int depth) { depths.put(node.nodeName(), depth); }
        public void tail(Node node, int depth) {}
    }, div);
    assertEquals(Integer.valueOf(0), depths.get("div"));
    assertEquals(Integer.valueOf(1), depths.get("p"));
    assertEquals(Integer.valueOf(2), depths.get("span"));
}

